import sqlite3

def handle(query, state):
    flag = state.get("flag", "")
    product_id = (query.get("id") or ["0"])[0]

    conn = sqlite3.connect(":memory:")
    cur = conn.cursor()

    cur.execute(
        "CREATE TABLE products (id INTEGER PRIMARY KEY, name TEXT, price REAL)"
    )
    cur.execute(
        "CREATE TABLE vault (id INTEGER PRIMARY KEY, label TEXT, token TEXT)"
    )
    cur.executemany(
        "INSERT INTO products (id, name, price) VALUES (?, ?, ?)",
        [
            (1, "Widget A", 9.99),
            (2, "Widget B", 14.99),
            (3, "Widget C", 4.99),
        ],
    )
    cur.execute(
        "INSERT INTO vault (id, label, token) VALUES (1, 'secret', ?)",
        (flag,),
    )
    conn.commit()

    sql = "SELECT id, name, price FROM products WHERE id = " + product_id
    try:
        cur.execute(sql)
        rows = cur.fetchall()
    except sqlite3.Error as e:
        conn.close()
        return 500, {"Content-Type": "text/plain"}, "DB error: " + str(e)

    conn.close()

    if not rows:
        return 200, {"Content-Type": "text/plain"}, "Product not found."

    lines = []
    for row in rows:
        lines.append("|".join(str(c) for c in row))
    return 200, {"Content-Type": "text/plain"}, "\n".join(lines)
